-- Do not edit: change the spec in model/ and regenerate.

CREATE OR REPLACE VIEW BRICKSURANCE.semantics.vw_s2_market_inputs
COMMENT = 'Published market-risk inputs for the Solvency II workbench: portfolio market value and the interest-rate stress at +/-100bps, via first-order duration sensitivity (stylised, standard-formula grade, no convexity). The interest-up loss is the interest-rate capital proxy. Self-contained (duration inlined) so it is a pure view; fn_duration / fn_stress_mv are the callable-tool equivalents. Publication contract - the S2 workbench re-points here rather than assuming numbers; migrating that workbench is out of scope. Grain: One row per asset portfolio.'
AS
WITH latest AS (
  SELECT portfolio_code, MAX(as_of_month) AS m
  FROM BRICKSURANCE.investment.position GROUP BY portfolio_code
),
mv AS (
  SELECT p.portfolio_code, SUM(p.market_value) AS base_mv
  FROM BRICKSURANCE.investment.position p
  JOIN latest l ON l.portfolio_code = p.portfolio_code AND p.as_of_month = l.m
  GROUP BY p.portfolio_code
),
dur AS (
  SELECT p.portfolio_code,
    SUM((datediff(ac.cashflow_month, current_date()) / 365.0)
        * (COALESCE(ac.coupon_amount,0) + COALESCE(ac.redemption_amount,0)) * p.nominal)
    / NULLIF(SUM((COALESCE(ac.coupon_amount,0) + COALESCE(ac.redemption_amount,0)) * p.nominal), 0)
      AS duration
  FROM BRICKSURANCE.investment.position p
  JOIN latest l ON l.portfolio_code = p.portfolio_code AND p.as_of_month = l.m
  JOIN BRICKSURANCE.investment.asset_cashflow ac ON ac.instrument_id = p.instrument_id
    AND ac.cashflow_month > current_date()
  GROUP BY p.portfolio_code
)
SELECT
  mv.portfolio_code,
  CAST(mv.base_mv AS DECIMAL(18,2)) AS base_market_value,
  CAST(mv.base_mv * (1 - COALESCE(dur.duration,0) * 0.01) AS DECIMAL(18,2)) AS mv_rates_up_100bps,
  CAST(mv.base_mv * (1 + COALESCE(dur.duration,0) * 0.01) AS DECIMAL(18,2)) AS mv_rates_down_100bps,
  CAST(mv.base_mv * COALESCE(dur.duration,0) * 0.01 AS DECIMAL(18,2)) AS interest_up_loss
FROM mv LEFT JOIN dur ON dur.portfolio_code = mv.portfolio_code;
